steps.run:
set -euo pipefail
manifest_path="${{ steps.release.outputs.manifest_path }}"
node -e '
  const fs = require("fs");
  const manifestPath = process.argv[1];
  const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
  manifest.tags = {
    ...(manifest.tags || {}),
    finalTag: manifest.finalTag,
    finalTagStatus: "pushed"
  };
  fs.writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
' "$manifest_path"

set -euo pipefail
version="${{ needs.prepare.outputs.version }}"
manifest_path="${{ needs.prepare.outputs.manifest_path }}"
open_manifest="$(find marketplace-results/open-vsx -type f -name "release-manifest-$version.json" -print -quit 2>/dev/null || true)"
visual_manifest="$(find marketplace-results/visual-studio -type f -name "release-manifest-$version.json" -print -quit 2>/dev/null || true)"
node -e '
  const fs = require("fs");
  const [manifestPath, openManifestPath, visualManifestPath] = process.argv.slice(1);
  const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
  for (const [key, filePath] of [["openVsx", openManifestPath], ["visualStudio", visualManifestPath]]) {
    if (!filePath || !fs.existsSync(filePath)) {
      continue;
    }
    const partial = JSON.parse(fs.readFileSync(filePath, "utf8"));
    if (partial.marketplaces?.[key]) {
      manifest.marketplaces = manifest.marketplaces || {};
      manifest.marketplaces[key] = partial.marketplaces[key];
    }
  }
  const targetComplete = (key) => {
    const entries = manifest.marketplaces?.[key] || {};
    return ["main", "notifier"].every((extension) => ["verified", "already-published"].includes(entries[extension]?.status));
  };
  const openComplete = targetComplete("openVsx");
  const visualComplete = targetComplete("visualStudio");
  const marketplaceComplete = openComplete && visualComplete;
  const releaseComplete = openComplete;
  manifest.status = releaseComplete
    ? marketplaceComplete
      ? "complete"
      : "complete-with-deferred-visual-studio"
    : "publish-failed";
  manifest.selectedTargets = ["visual-studio", "open-vsx"];
  manifest.options = {
    ...(manifest.options || {}),
    target: "all",
    requiredCompletionTargets: ["github-release-assets", "open-vsx"],
    visualStudioBlocking: false
  };
  manifest.releaseCompletion = {
    marketplaceComplete,
    openVsxComplete: openComplete,
    requiredTargets: ["github-release-assets", "open-vsx"],
    visualStudioBlocking: false,
    visualStudioComplete: visualComplete
  };
  manifest.githubRelease = {
    ...(manifest.githubRelease || {}),
    assets: (manifest.artifacts || []).map((artifact) => artifact.path),
    finalTag: manifest.finalTag,
    releaseRef: manifest.releaseRef,
    status: "assets-uploaded",
    uploadedAt: new Date().toISOString()
  };
  manifest.tags = {
    ...(manifest.tags || {}),
    finalTag: manifest.finalTag,
    finalTagStatus: "pushed"
  };
  fs.writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  if (process.env.GITHUB_OUTPUT) {
    fs.appendFileSync(
      process.env.GITHUB_OUTPUT,
      `open_vsx_complete=${openComplete}\nvisual_studio_complete=${visualComplete}\nmarketplace_complete=${marketplaceComplete}\nrelease_complete=${releaseComplete}\n`
    );
  }
' "$manifest_path" "$open_manifest" "$visual_manifest"
